  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `create_by_name` varchar(50) DEFAULT NULL COMMENT '创建人名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改人ID',
  `update_by_name` varchar(50) DEFAULT NULL COMMENT '修改人名称',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `animal_photo` varchar(255) DEFAULT NULL COMMENT '寄养宠物照片',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='笼位/房间表';

CREATE TABLE `submit` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) DEFAULT NULL COMMENT '提交名称',
  `img` varchar(255) DEFAULT NULL COMMENT '提交图片地址',
  `time` datetime DEFAULT NULL COMMENT '上报时间',
  `status` tinyint(2) NOT NULL DEFAULT '1' COMMENT '处理状态：1-待处理，2-已处理',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `create_by_name` varchar(50) DEFAULT NULL COMMENT '创建人名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改人ID',
  `update_by_name` varchar(50) DEFAULT NULL COMMENT '修改人名称',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='提交记录表';

CREATE TABLE `tag` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键标识',
  `title` varchar(100) DEFAULT NULL COMMENT '标签名称（如：温顺、活泼、训练有素等）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `create_by_name` varchar(50) DEFAULT NULL COMMENT '创建人名称',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改人ID',
  `update_by_name` varchar(50) DEFAULT NULL COMMENT '修改人名称',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tag_title` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='商品标签字典表';

CREATE TABLE `user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键标识',
  `username` varchar(50) DEFAULT NULL COMMENT '登录用户名（唯一）',
  `password` varchar(100) DEFAULT NULL COMMENT '登录密码（BCrypt 密文）',
  `role` tinyint(2) DEFAULT NULL COMMENT '用户角色：1-普通用户，2-演示用户，3-管理员',
  `status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '账户状态：0-正常，1-封号',
  `nickname` varchar(20) DEFAULT NULL COMMENT '用户昵称（页面展示名）',
  `avatar` varchar(255) DEFAULT NULL COMMENT '用户头像图片地址',
  `mobile` varchar(13) DEFAULT NULL COMMENT '绑定手机号',
  `email` varchar(50) DEFAULT NULL COMMENT '绑定邮箱',
  `gender` varchar(1) DEFAULT NULL COMMENT '性别（男/女）',
  `description` longtext COMMENT '个人简介/个性签名',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `score` int(11) DEFAULT '0' COMMENT '用户积分',
  `push_email` varchar(40) DEFAULT NULL COMMENT '消息推送接收邮箱',
  `push_switch` tinyint(1) DEFAULT '0' COMMENT '消息推送开关：0-关闭，1-开启',
  `token` varchar(32) DEFAULT NULL COMMENT '登录会话令牌（32位UUID）',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `create_by_name` varchar(50) DEFAULT NULL COMMENT '创建人名称',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改人ID',
  `update_by_name` varchar(50) DEFAULT NULL COMMENT '修改人名称',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_username` (`username`),
  KEY `idx_user_token` (`token`),
  KEY `idx_user_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='用户表（含普通用户和管理员）';

DELIMITER //
CREATE PROCEDURE `add_column_if_not_exists`(
    IN p_table_name VARCHAR(64) CHARACTER SET utf8mb4,
    IN p_column_name VARCHAR(64) CHARACTER SET utf8mb4,
    IN p_column_definition VARCHAR(200) CHARACTER SET utf8mb4
)
BEGIN
    DECLARE v_column_exists INT DEFAULT 0;
    SELECT COUNT(*) INTO v_column_exists
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = p_table_name
      AND COLUMN_NAME = p_column_name;
    IF v_column_exists = 0 THEN
        SET @sql = CONCAT('ALTER TABLE `', p_table_name, '` ADD COLUMN `', p_column_name, '` ', p_column_definition);
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END//
DELIMITER ;

DELIMITER //
CREATE PROCEDURE `modify_column_if_exists`(
    IN p_table_name VARCHAR(64) CHARACTER SET utf8mb4,
    IN p_column_name VARCHAR(64) CHARACTER SET utf8mb4,
    IN p_column_definition VARCHAR(200) CHARACTER SET utf8mb4
)
BEGIN
    DECLARE v_column_exists INT DEFAULT 0;
    SELECT COUNT(*) INTO v_column_exists
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = p_table_name
      AND COLUMN_NAME = p_column_name;
    IF v_column_exists > 0 THEN
        SET @sql = CONCAT('ALTER TABLE `', p_table_name, '` MODIFY COLUMN `', p_column_name, '` ', p_column_definition);
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END//
DELIMITER ;

SET FOREIGN_KEY_CHECKS = 1;
